INSERT OR IGNORE INTO "core_configuration" VALUES ('INTEGRATION_DESCRIPTION_PARTS','autodelic','<img src="https://dijelovi.delicauto.com/static/autodelic/logo.jpg" > 

<h2>PART_TITLE</h2>
<p>Interna šifra: PART_CODE</p>
VEHICLE_DETAILS

<p>Bavimo se uvozom i prodajom originalnih polovnih auto dijelova za sve vrste vozila.</p>
<p>Svi dijelovi se mogu ugraditi u našem auto servisu.</p>

<p>- Garancija na ispravnost 7 dana</p>
<p>- Dijelove šaljemo brzom poštom</p>
<p>- Nalazimo se na Pavlovića putu br 13, 500m sa lijeve strane posle tržnog centra FIS.</p>
 
<h2 style="color: #665CAC">Telefon / Viber 066027888</h2>',NULL,NULL,NULL,NULL);
